import{z as n,x as i,o as B,c as p,q as r,j as t,D as a,d as e,s as l,S as o,b as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"系统调用的路径","description":"","frontmatter":{"title":"系统调用的路径","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/osk-syscall-path.md","filePath":"cs/osk-syscall-path.md","lastUpdated":1791063341000}'),C={name:"cs/osk-syscall-path.md"};function d(c,E,m,D,F,u){const A=i("Mermaid");return B(),p("div",null,[E[2]||(E[2]=r('<h1 id="系统调用的路径" tabindex="-1">系统调用的路径 <a class="header-anchor" href="#系统调用的路径" aria-label="Permalink to &quot;系统调用的路径&quot;">​</a></h1><div class="epigraph"><p>系统调用不是函数调用：它是一次有编号的越界，路径上每一步都在检查上一步放进来的东西。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Arpaci-Dusseau, OSTEP 整理</footer></div><p><a href="/cs/osk-fs-implementation">上一课</a>的 write 从 VFS 走到了设备；本课补前半程：用户态那条指令如何变成对 write 的内核调用。<a href="/cs/syscall-abi">系统调用 ABI</a> 已定调用号、参数槽与返回约定，<a href="/cs/copy-from-user">copy_from_user</a> 给了安全拷贝；缺口是两者之间那条真实路径——进入、分派、校验、返回，以及路径上挂着的每个钩子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一台机器上有几百个系统调用、多种 ABI（64 位与 32 位兼容）并存，还有多个安全机制要在入口表态。实现若让每个调用各自处理保存现场与越界检查，每一处都是一个独立的漏洞源。不这么做会错在哪：把用户指针直接交给内核解引用，坏指针会让内核崩在用户地址上，或被竞态改成指向内核；分派前不检查编号范围，越界编号就是一次任意跳转。主干课把 ABI 与安全拷贝拆开讲过，路径本身——五步在什么顺序里咬合——始终没给，这正是本课的对象。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路径固定五步。进入：syscall 一类指令陷入，切到每 CPU 的内核栈，把用户寄存器整组存成现场帧——这是全系统唯一「保存全部」的地方，上一课的上下文切换之所以只换栈，正因为这里已经存了。过滤：seccomp 的 BPF 程序先过一遍编号与参数，拒绝即原地返回，真实现还没开始。分派：以编号为下标查系统调用表，超出表长返回错误码，不存在猜测。执行：每调用的包装层把寄存器槽映射成 C 参数，指针参数先过范围检查，再交给 copy_from_user 与 copy_to_user 拷进拷出。返回：返回值写回现场帧，顺路检查挂起信号与跟踪停点，然后一条指令回到用户态。</p><p><span class="marginnote">数字实例：Linux x86-64 上 write 的调用号是 1、open 是 2，用户程序把 1 放进 rax 再执行 syscall；内核就拿这个 1 当下标去系统调用表取函数指针——所谓「查表」，就是一次 C 数组取值，越界检查只是拿表长比一下。</span></p><p><span class="marginnote">术语翻译：seccomp 过滤就是给系统调用入口装一道可编程门卫——内核替你跑一小段 BPF 字节码，它只拿到调用号和参数这几个数，说拒绝就当场打回。容器正是靠它把几百个系统调用砍成白名单里的几十个。</span></p>',9)),(B(),t(o,null,{default:a(()=>[l(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E9%99%B7%E5%85%A5%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20SAVE%5B%22%E5%88%87%E5%86%85%E6%A0%B8%E6%A0%88%EF%BC%8C%E5%AD%98%E6%95%B4%E7%BB%84%E7%8E%B0%E5%9C%BA%E5%B8%A7%22%5D%0A%20%20SAVE%20--%3E%20SEC%7B%22seccomp%20%E8%BF%87%E6%BB%A4%E7%BC%96%E5%8F%B7%E4%B8%8E%E5%8F%82%E6%95%B0%22%7D%0A%20%20SEC%20--%3E%7C%E6%8B%92%E7%BB%9D%7C%20DENY%5B%22%E5%8E%9F%E5%9C%B0%E8%BF%94%E5%9B%9E%E9%94%99%E8%AF%AF%22%5D%0A%20%20SEC%20--%3E%7C%E6%94%BE%E8%A1%8C%7C%20TBL%5B%22%E6%8C%89%E7%BC%96%E5%8F%B7%E6%9F%A5%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E8%A1%A8%22%5D%0A%20%20TBL%20--%3E%20IMPL%5B%22%E5%8C%85%E8%A3%85%E5%B1%82%EF%BC%9A%E8%8C%83%E5%9B%B4%E6%A3%80%E6%9F%A5%E4%B8%8E%E5%AE%89%E5%85%A8%E6%8B%B7%E8%B4%9D%22%5D%0A%20%20IMPL%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E5%80%BC%E5%86%99%E5%9B%9E%EF%BC%8C%E6%A3%80%E6%9F%A5%E4%BF%A1%E5%8F%B7%E4%B8%8E%E5%81%9C%E7%82%B9%22%5D%0A%20%20RET%20--%3E%20BACK%5B%22%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%E6%80%81%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=s("p",null,"为什么一条共用路径能撑住整个 ABI：编号是版本化接口，表就是兼容层——32 位调用有独立的表与参数转换，新旧调用并存互不干扰。vDSO 是同一思路的另一半：时间读取、缓存参数这类不需要特权的数据，内核把结果页映射进用户空间，调用根本不进路径——省掉的正是五步里最贵的那两步往返。信号为什么挂在返回路径：内核不能在任意执行点打断自己，只能约定「回到用户态之前」处理挂起信号；这也解释了为什么信号处理总要等到陷入返回，而不是立即执行。校验为什么分两级：范围检查只判「地址落在用户半空间」，映射与否交给 copy_from_user 内部的缺页机制兜底——两级各管一半，合起来才既快又安全。",-1)),(B(),t(o,null,{default:a(()=>[l(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E7%94%A8%E6%88%B7%E7%A8%8B%E5%BA%8F%E8%A6%81%E8%AF%BB%E6%97%B6%E9%97%B4%22%5D%20--%3E%20Q%7B%22%E6%95%B0%E6%8D%AE%E9%9C%80%E8%A6%81%E7%89%B9%E6%9D%83%E6%89%8D%E8%83%BD%E6%8B%BF%E5%90%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E8%B5%B0%20vDSO%22%7C%20VDSO%5B%22%E7%9B%B4%E6%8E%A5%E8%AF%BB%E5%86%85%E6%A0%B8%E6%98%A0%E5%B0%84%E8%BF%9B%E7%94%A8%E6%88%B7%E7%A9%BA%E9%97%B4%E7%9A%84%E6%95%B0%E6%8D%AE%E9%A1%B5%22%5D%0A%20%20VDSO%20--%3E%20R1%5B%22%E6%99%AE%E9%80%9A%E5%87%BD%E6%95%B0%E8%B0%83%E7%94%A8%E8%BF%94%E5%9B%9E%22%5D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%EF%BC%8C%E8%B5%B0%E5%AE%8C%E6%95%B4%E8%B7%AF%E5%BE%84%22%7C%20TRAP%5B%22%E9%99%B7%E5%85%A5%E5%86%85%E6%A0%B8%EF%BC%8C%E5%88%87%E6%A0%88%E5%AD%98%E7%8E%B0%E5%9C%BA%E5%B8%A7%22%5D%0A%20%20TRAP%20--%3E%20DISP%5B%22%E8%BF%87%E6%BB%A4%E5%90%8E%E6%8C%89%E7%BC%96%E5%8F%B7%E6%9F%A5%E8%A1%A8%E5%88%86%E6%B4%BE%22%5D%0A%20%20DISP%20--%3E%20EXEC%5B%22%E5%86%85%E6%A0%B8%E6%89%A7%E8%A1%8C%EF%BC%8C%E8%BF%94%E5%9B%9E%E5%80%BC%E5%86%99%E5%9B%9E%E7%8E%B0%E5%9C%BA%E5%B8%A7%22%5D%0A%20%20EXEC%20--%3E%20R2%5B%22%E6%A3%80%E6%9F%A5%E4%BF%A1%E5%8F%B7%E5%90%8E%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%E6%80%81%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">常见误区：初学者容易以为读个时间也得陷入内核。实际上 gettimeofday 这类只读数据由 vDSO 在用户态直接算出，一次普通函数调用就返回——省掉两次模式切换。对每秒调用百万次的时间读取，这是数量级的差别。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>陷入的硬件机制是<a href="/cs/kernel-user">内核与用户态</a>与异常入口课的对象，本课不写指令编码与时序；<a href="/cs/user-kernel-split">用户/内核分裂</a>给的是地址侧的界，本课给的是控制流侧的路。不同内核版本的入口实现差异很大——有的架构用纯汇编入口，有的已改写成 C——课序钉的是五步这个不变序，不是某个版本的函数名。虚拟化的陷入-模拟是另一条更长的路径，主干隔离单元的对象，也不在此处。</p><p><span class="marginnote">旧 x86 的 vsyscall 页是 vDSO 的前身：固定地址、可被恶意程序当作可靠跳板，后来被改成陷阱再模拟并在仿真里返回——省一次往返的捷径若不做隔离，最后会被安全问题逼着加回一整层路径。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五步固定序：存现场帧、安全过滤、查表分派、包装校验、恢复返回。</li><li>现场帧是唯一整组保存；上下文切换只换栈的便宜，建立在它之上。</li><li>系统调用表就是 ABI 的版本化实现；vDSO 把无特权需求的部分挪出路径。</li><li>指针参数两级校验：范围检查管边界，安全拷贝的缺页机制管映射。</li><li>出处：Tanenbaum and Bos, <em>Modern Operating Systems</em>；Arpaci-Dusseau, <em>OSTEP</em>；Love, <em>Linux Kernel Development</em>。</li></ul>',6))])}const f=n(C,[["render",d]]);export{_ as __pageData,f as default};
